 1	method TriangleNumber(N: int) returns (t: int)
 2	    requires N >= 0
 3	    ensures t == N * (N + 1) / 2
 4	{
 5	    t := 0;
 6	    var n := 0;
 7	    while n < N
 8	        invariant t == n * (n + 1) / 2
 9	        decreases N - n;// can be left out because it is guessed correctly by Dafny
10	    {
11	        n:= n + 1;
12	        t := t + n;
13	    }
14	}

