     1	method TriangleNumber(N: int) returns (t: int)
     2	    requires N >= 0
     3	    ensures t == N * (N + 1) / 2
     4	{
     5	    t := 0;
     6	    var n := 0;
     7	    while n < N
     8	        invariant 0 <= n <= N
     9	        invariant t == n * (n + 1) / 2
    10	        decreases N - n;// can be left out because it is guessed correctly by Dafny
    11	    {
    12	        n:= n + 1;
    13	        t := t + n;
    14	    }
    15	}
{"spec_element": "invariant",
 "proof_obligation": "bridge",
 "diagnosis": "The loop invariant only states t == n*(n+1)/2 and lacks the bound n <= N. On exit Dafny knows only the invariant and !(n < N), i.e. n >= N, so it cannot conclude n == N and hence cannot derive t == N*(N+1)/2. Adding invariant 0 <= n <= N bridges invariant + exit condition to the postcondition."}

